  weapon: '#ff0000',
};
let startX, startY;

// Flood fill to check reachability
function floodFill(x, y) {
  if (x < 0 || x >= 500 || y < 0 || y >= 500) return;
  if (map[y][x] !== 0) return;
  map[y][x] = 1;
  floodFill(x + 1, y);
  floodFill(x - 1, y);
  floodFill(x, y + 1);
  floodFill(x, y - 1);
}

// Generate random room
function generateRoom(x, y, w, h) {
  for (let i = 0; i < w; i++) {
    for (let j = 0; j < h; j++) {
      map[y + i][x + j] = 0;
      floodFill(x + j, y + i);
    }
  }
}

// Generate corridor between rooms
function generateCorridor(x1, y1, x2, y2) {
  const dx = Math.abs(x2 - x1);
  const dy = Math.abs(y2 - y1);
  const sx = x1 < x2 ? 1 : -1;
  const sy = y1 < y2 ? 1 : -1;
  let x = x1;
  let y = y1;
  while (x !== x2 || y !== y2) {
    map[y][x] = 0;
    floodFill(x, y);
    x += sx;
    y += sy;
  }
}

